38	// ---- help model: the user-facing surface rendered as a command tree --------
39	//
40	// `run`'s two subcommand groups -- the modes (the composition axis) ...
41	struct ModeRow {
42	  const char* name;
43	  const char* brief;
44	};
45	constexpr ModeRow kRunModes[] = {
46	    {"fast", "QEMU only -- functional, full speed"},
47	    {"cycle", "one cycle-accurate engine, from reset"},
48	    {"hybrid", "QEMU fast-forwards, then vsim measures the ROI"},
49	};
50	
51	// `list`'s targets. `fixtures` (internal test ELFs) is a developer target,
52	// shown only under ANDESIM_DEV; the product lists user-facing models/engines.
53	struct TargetRow {
54	  const char* name;
55	  const char* brief;
56	  bool dev;
57	};
58	constexpr TargetRow kListTargets[] = {
59	    {"models", "the modes and their engines", false},
60	    {"engines", "discovered cycle-accurate engines", false},
61	    {"fixtures", "internal test ELFs (developer target)", true},
62	};
63	
64	// ... and `run`'s options. Each `flag` carries its own leading indent (the pc
65	// boundaries nest under --trigger pc). `tag` marks a required option (and WHEN
66	// it is required); `dev` hides it unless ANDESIM_DEV is set.
67	struct OptRow {
68	  const char* flag;  // includes its own leading indent
69	  const char* tag;
70	  const char* brief;
71	  bool dev;
72	};
73	constexpr OptRow kRunOpts[] = {
74	    {"  --mode fast|cycle|hybrid", "REQUIRED", "which mode to run", false},
75	    {"  --trigger marker|pc", "REQUIRED for hybrid", "the ROI delimiter", false},
76	    {"    --pc-start <sym|0x>", "REQUIRED for --trigger pc", "ROI start boundary", false},
77	    {"    --pc-end <sym|0x>", "REQUIRED for --trigger pc", "ROI end boundary", false},
78	    {"  --engine <id>", "", "pick an engine, e.g. vsim:ax45mpv_premium (default: the sole one)", false},
79	    {"  --mem-size <spec>", "", "guest RAM, e.g. 256M / 2G (hybrid: max 2G; fast: QEMU -m; cycle: ignored)", false},
80	    {"  --dry-run", "", "print the exact engine command(s) and exit, running nothing (fast/cycle/hybrid)", false},
81	    {"  --print-memmap", "", "print the hybrid guest memory map and exit, running nothing (hybrid only; ELF optional)", false},
82	    {"  --verify", "", "cross-check the hybrid run against a QEMU oracle", false},
83	    {"  --kanata <file>", "", "write a Kanata pipeline trace of the ROI (hybrid only; open in Konata)", false},
84	    {"    --objdump <file>", "", "embed that objdump -d dump's disassembly in the trace (requires --kanata)", false},
85	    {"  --gdb", "", "pause at startup for a debugger (fast: QEMU stub; cycle: vsim JTAG + $ICEMAN; not hybrid)", false},
86	    {"  --gdb-port <port>", "", "override the --gdb port (fast 1234, cycle 9104)", false},
87	    {"  --log-level <0-6>", "", "verbosity, vsim's scale: 0=trace 1=debug 2=info 3=warn 4=error 5=critical 6=off (default 2: program output + the cycle figure)", false},
88	    {"  --log-file <file>", "", "append EVERY level's messages (timestamped) to <file>; the console keeps --log-level", false},
89	    {"  --step-timeout-ms <ms>", "", "hybrid per-leg spawn timeout (default 90000); raise it for a large ROI on the cycle-accurate leg", false},
90	    {"  -- <args...>", "", "forward everything after -- verbatim to the engine (fast/cycle); hybrid rejects -- args, EXCEPT --runtime linux, where they are app argv", false},
91	};
