3	namespace andes_sim {
4	namespace {
5	
6	// Try to read an option's value at args[i]. Supports both `--flag value`
7	// (consumes the next token, advancing i) and `--flag=value`.
8	//   returns  1 = matched, `out` set
9	//            0 = this token is not `flag`
10	//           -1 = matched `--flag` but no value follows
11	int match_opt(const std::vector<std::string>& args, size_t& i,
12	              const std::string& flag, std::string& out) {
13	  const std::string& a = args[i];
14	  if (a == flag) {
15	    if (i + 1 >= args.size()) return -1;
16	    out = args[++i];
17	    return 1;
18	  }
19	  const std::string pfx = flag + "=";
20	  if (a.starts_with(pfx)) {
21	    out = a.substr(pfx.size());
22	    return 1;
23	  }
24	  return 0;
25	}
26	
27	}  // namespace
28	
29	bool is_subcommand(std::string_view name) {
30	  return name == "run" || name == "list" || name == "doctor" ||
31	         name == "profile";
32	}
33	
34	Cli parse_cli(const std::vector<std::string>& args) {
35	  Cli c;
36	  if (args.empty()) return c;  // no subcommand; caller prints usage
37	
38	  // First token is the subcommand, unless it is a top-level help request.
39	  if (args[0] == "-h" || args[0] == "--help") {
40	    c.help = true;
41	    return c;
42	  }
43	
44	  // `run` is the default command: any other first token is `run`'s own
45	  // first argument (a flag or the ELF), not a subcommand.
46	  size_t first = 1;
47	  if (is_subcommand(args[0])) {
48	    c.subcommand = args[0];
49	  } else {
50	    c.subcommand = "run";
51	    first = 0;
52	  }
53	
54	  for (size_t i = first; i < args.size(); ++i) {
55	    const std::string& a = args[i];
56	
57	    if (a == "--") {  // the passthrough boundary: rest is verbatim
58	      c.has_passthrough = true;
59	      for (size_t j = i + 1; j < args.size(); ++j) c.passthrough.push_back(args[j]);
60	      break;
61	    }
62	    if (a == "-h" || a == "--help") {
63	      c.help = true;
64	      continue;
65	    }
66	    if (a == "--dry-run") {
67	      c.dry_run = true;
68	      continue;
69	    }
70	    if (a == "--print-memmap") {
71	      c.print_memmap = true;
72	      continue;
73	    }
74	    if (a == "--verify") {
75	      c.verify = true;
76	      continue;
77	    }
78	    if (a == "--gdb") {
79	      c.gdb = true;
80	      continue;
81	    }
82	    // profile's report toggles: each --no-* has a positive spelling that
83	    // re-enables it, so the last one on the line wins.
84	    if (a == "--raw") {
85	      c.raw = true;
86	      continue;
87	    }
88	    if (a == "--llm" || a == "--no-llm") {
89	      c.llm = (a == "--llm");
90	      continue;
91	    }
92	    if (a == "--optimize-rvv" || a == "--no-optimize-rvv") {
93	      c.optimize_rvv = (a == "--optimize-rvv");
94	      continue;
95	    }
96	    if (a == "--no-source") {
97	      c.no_source = true;
98	      continue;
99	    }
100	
101	    const struct {
102	      const char* flag;
103	      std::string* out;
104	    } opts[] = {{"--mode", &c.model},
105	                {"--engine", &c.engine},
106	                {"--trigger", &c.trigger},
107	                {"--pc-start", &c.pc_start},
108	                {"--pc-end", &c.pc_end},
109	                {"--mem-size", &c.mem_size},
110	                {"--mmap-size", &c.mem_size},  // retired spelling, same knob
111	                {"--runtime", &c.runtime},
112	                {"--kanata", &c.kanata},
113	                {"--objdump", &c.objdump},
114	                {"--log-level", &c.log_level},
115	                {"--log-file", &c.log_file},
116	                {"--step-timeout-ms", &c.step_timeout_ms},
117	                {"--gdb-port", &c.gdb_port},
118	                {"--limit", &c.limit},
119	                {"--min-iters", &c.min_iters},
120	                {"--addr2line", &c.addr2line}};
121	    bool consumed = false;
122	    for (const auto& o : opts) {
123	      int r = match_opt(args, i, o.flag, *o.out);
124	      if (r < 0) { c.error = std::string("missing value for ") + o.flag; return c; }
125	      if (r > 0) { consumed = true; break; }
126	    }
127	    if (consumed) continue;
128	
129	    if (a.size() > 1 && a[0] == '-') {
130	      c.error = "unknown option: " + a;
131	      return c;
132	    }
133	    c.positional.push_back(a);
134	  }
135	
136	  return c;
137	}
138	
139	Cli parse_cli(int argc, char** argv) {
140	  std::vector<std::string> args;
141	  args.reserve(argc > 1 ? static_cast<size_t>(argc - 1) : 0);
142	  for (int i = 1; i < argc; ++i) args.emplace_back(argv[i]);
143	  return parse_cli(args);
144	}
145	
146	}  // namespace andes_sim
