1	// Placeholder substitution for engine invoke templates (minus QEMU2). The
2	// argv *shape* lives in each engine's `invoke` template (from
3	// `--describe`, see docs/engine_interface.md) and build_argv fills the
4	// {placeholders} from a context map. The framework thus keeps zero per-engine
5	// argv code: a new engine ships its own template.
6	#ifndef ANDESIM_ARGV_HPP
7	#define ANDESIM_ARGV_HPP
8	
9	#include <cctype>
10	#include <cstdio>
11	#include <cstring>
