6	
7	// Expand every "{key}" in `s` from `ctx`. A "{" with no closing "}" is a
8	// literal. An unknown key sets `err` and returns false (out is undefined).
9	bool subst(const std::string& s, const std::map<std::string, std::string>& ctx,
10	           std::string& out, std::string& err) {
11	  out.clear();
12	  for (size_t i = 0; i < s.size();) {
13	    if (s[i] != '{') {
14	      out += s[i++];
15	      continue;
16	    }
17	    const size_t close = s.find('}', i + 1);
18	    if (close == std::string::npos) {  // unbalanced brace: keep literally
19	      out += s[i++];
20	      continue;
21	    }
22	    const std::string key = s.substr(i + 1, close - i - 1);
23	    const auto it = ctx.find(key);
24	    if (it == ctx.end()) {
25	      err = "unknown placeholder '{" + key + "}'";
26	      return false;
27	    }
28	    out += it->second;
29	    i = close + 1;
30	  }
31	  return true;
32	}
33	
34	}  // namespace
35	
36	std::vector<std::string> build_argv(const std::vector<std::string>& tmpl,
37	                                    const std::map<std::string, std::string>& ctx,
38	                                    std::string& err) {
39	  std::vector<std::string> out;
40	  out.reserve(tmpl.size());
41	  for (const std::string& arg : tmpl) {
42	    std::string filled;
43	    if (!subst(arg, ctx, filled, err)) return {};
44	    out.push_back(std::move(filled));
45	  }
46	  err.clear();
47	  return out;
48	}
