27	std::vector<std::string> read_lines(const fs::path& p, bool& ok) {
28	  std::ifstream f(p);
29	  std::vector<std::string> lines;
30	  ok = static_cast<bool>(f);
31	  if (!ok) return lines;
32	  std::string line;
33	  while (std::getline(f, line)) lines.push_back(line);
34	  return lines;
35	}
