37	// Match a Makefile variable assignment at column 0: `VAR :?= <body>` where
38	// VAR is [A-Z_][A-Z0-9_]*. Mirrors the Python regex anchor. On success sets
39	// `var` and `body` (the text after `=`, continuation backslash included).
40	bool parse_assignment(const std::string& line, std::string& var,
41	                      std::string& body) {
42	  const size_t n = line.size();
43	  if (n == 0) return false;
44	  char c0 = line[0];
45	  if (!((c0 >= 'A' && c0 <= 'Z') || c0 == '_')) return false;
46	  size_t p = 0;
47	  while (p < n) {
48	    char c = line[p];
49	    if ((c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_') ++p;
50	    else break;
51	  }
52	  var = line.substr(0, p);
53	  while (p < n && (line[p] == ' ' || line[p] == '\t')) ++p;  // \s*
54	  if (p < n && line[p] == ':') ++p;                          // :?
55	  if (p >= n || line[p] != '=') return false;                // =
56	  ++p;
57	  body = line.substr(p);
58	  return true;
59	}
60	
61	struct Fixture {
62	  std::string name;
63	  std::string family;
64	};
65	
66	// Extract fixture (name, family) rows from tests/fixtures/Makefile in stable,
67	// family-grouped, file order; dedupe globally; append handoff_roundtrip last.
68	std::vector<Fixture> parse_fixtures(const std::vector<std::string>& lines) {
69	  static const std::pair<std::string, std::string> interesting[] = {
70	      {"RT_FIXTURES", "asm"},
71	      {"RT_C_FIXTURES", "c"},
72	      {"RT_C_V_FIXTURES", "c+rvv"},
73	      {"PROBE_V_FIXTURES", "probe"},
74	  };
75	  std::vector<Fixture> rows;
76	  std::set<std::string> seen;
77	
78	  for (size_t k = 0; k < lines.size(); ++k) {
79	    std::string var, body;
80	    if (!parse_assignment(lines[k], var, body)) continue;
81	    std::string family;
82	    for (const auto& it : interesting)
83	      if (it.first == var) { family = it.second; break; }
84	    if (family.empty()) continue;
85	
86	    // Splice continuation lines: a trailing backslash + newline becomes a space.
87	    size_t li = k;
88	    while (!body.empty() && body.back() == '\\') {
89	      body.pop_back();
90	      body.push_back(' ');
91	      if (++li < lines.size()) body += lines[li];
92	      else break;
93	    }
94	
95	    std::istringstream iss(body);
96	    std::string name;
97	    while (iss >> name)
98	      if (seen.insert(name).second) rows.push_back({name, family});
99	  }
100	
101	  // handoff_roundtrip is not in a *_FIXTURES var; list it explicitly.
102	  if (seen.insert("handoff_roundtrip").second)
103	    rows.push_back({"handoff_roundtrip", "asm"});
104	
105	  return rows;
106	}
