108	int list_fixtures() {
109	  fs::path mk = repo_root() / "tests" / "fixtures" / "Makefile";
110	  bool ok;
111	  std::vector<std::string> lines = read_lines(mk, ok);
112	  if (!ok) {
113	    std::fprintf(stderr, "andesim: missing %s\n", mk.c_str());
114	    return 2;
115	  }
116	  std::vector<Fixture> rows = parse_fixtures(lines);
117	
118	  size_t width = 0;
119	  for (const Fixture& r : rows) width = std::max(width, r.name.size());
120	
121	  std::printf("%s  FAMILY\n", ljust("FIXTURE", width).c_str());
122	  for (const Fixture& r : rows)
123	    std::printf("%s  %s\n", ljust(r.name, width).c_str(), r.family.c_str());
124	  return 0;
125	}
