127	int list_models() {
128	  size_t wn = 5, we = 7;  // header widths: MODEL, ENGINES
129	  for (const Model& m : kModels) {
130	    wn = std::max(wn, m.name.size());
131	    we = std::max(we, m.engines.size());
132	  }
133	  std::printf("%s  %s  NOTES\n", ljust("MODEL", wn).c_str(),
134	              ljust("ENGINES", we).c_str());
135	  for (const Model& m : kModels)
136	    std::printf("%s  %s  %s\n", ljust(std::string(m.name), wn).c_str(),
137	                ljust(std::string(m.engines), we).c_str(),
138	                std::string(m.notes).c_str());
139	  return 0;
140	}
