142	int list_engines() {
143	  Discovery disc = discover_engines();
144	
145	  // Columns describe engine identity only. Triggers are a hybrid-MODEL option
146	  // (see `list models` / `run --help`), not an engine attribute, so no TRIGGERS
147	  // column here.
148	  size_t we = 6, wt = 4, wk = 4;  // ENGINE, TYPE, KIND headers
149	  for (const EngineDescriptor& e : disc.engines) {
150	    we = std::max(we, e.id.size());
151	    wt = std::max(wt, e.type.size());
152	    wk = std::max(wk, e.kind.size());
153	  }
154	
155	  // Hardware params from each engine's --describe; "-" = not reported.
156	  // CACHE is the platform shared cache (L2C on 45-series, L3C on 46/66):
157	  // appended LAST so column-position consumers of the earlier fields hold.
158	  std::printf("%s  %s  %s  XLEN  VLEN  DLEN  ELEN  CACHE\n",
159	              ljust("ENGINE", we).c_str(), ljust("TYPE", wt).c_str(),
160	              ljust("KIND", wk).c_str());
161	  for (const EngineDescriptor& e : disc.engines)
162	    std::printf("%s  %s  %s  %-4s  %-4s  %-4s  %-4s  %s\n",
163	                ljust(e.id, we).c_str(),
164	                ljust(e.type, wt).c_str(), ljust(e.kind, wk).c_str(),
165	                vlen_str(e.xlen).c_str(), vlen_str(e.vlen).c_str(),
166	                vlen_str(e.dlen).c_str(), vlen_str(e.elen).c_str(),
167	                e.shared_cache_str().c_str());
168	
169	  // Binaries that could not self-describe are reported, never silently dropped.
170	  for (const std::string& w : disc.warnings)
171	    std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
172	  return 0;
173	}
