177	int cmd_list(const Cli& cli) {
178	  // `fixtures` lists internal test ELFs -- a developer target, gated behind
179	  // ANDESIM_DEV so the release product offers only user-facing models/engines.
180	  const char* targets = is_dev_mode() ? "fixtures|models|engines" : "models|engines";
181	  if (cli.positional.empty()) {
182	    std::fprintf(stderr, "andesim list: expected one of %s\n", targets);
183	    return 2;
184	  }
185	  const std::string& t = cli.positional[0];
186	  if (t == "fixtures" && is_dev_mode()) return list_fixtures();
187	  if (t == "models") return list_models();
188	  if (t == "engines") return list_engines();
189	  std::fprintf(stderr, "andesim list: unknown target '%s' (want %s)\n",
190	               t.c_str(), targets);
191	  return 2;
192	}
