95	std::vector<Row> doctor_submodules() {
96	  const fs::path root = repo_root();
97	  struct M {
98	    const char* name;
99	    fs::path marker;
100	    const char* rel;  // marker, repo-relative (the PASS detail)
101	  };
102	  // QEMU and vsim are no longer submodules -- both are integrated as prebuilt
103	  // external binaries, checked in the artifacts section (qemu/vsim rows) via
104	  // VSIM_QEMU / VSIM_BIN_DIR. The one remaining submodule is the shared ABI.
105	  const M ms[] = {
106	      {"include/ (abi)", root / "include" / "hybrid" / "state_abi.h",
107	       "include/hybrid/state_abi.h"},
108	  };
109	  std::vector<Row> rows;
110	  for (const M& m : ms) {
111	    if (fs::is_regular_file(m.marker))
112	      rows.push_back({m.name, "PASS", m.rel});
113	    else
114	      rows.push_back({m.name, "FAIL",
115	                      "missing " + m.marker.string() +
116	                          " -- run 'git submodule update --init --recursive'"});
117	  }
118	  return rows;
119	}
