121	// --- toolchain --------------------------------------------------------------
122	
123	// First PATH directory holding an executable non-directory named `tool`, joined
124	// the way shutil.which reports it (dir + '/' + tool). "" if not found.
125	std::string which(const std::string& tool) {
126	  const char* path = std::getenv("PATH");
127	  if (!path) return "";
128	  const std::string p(path);
129	  for (size_t i = 0; i <= p.size();) {
130	    size_t j = p.find(':', i);
131	    if (j == std::string::npos) j = p.size();
132	    std::string dir = p.substr(i, j - i);
133	    i = j + 1;
134	    if (dir.empty()) continue;
135	    std::string cand = dir.back() == '/' ? dir + tool : dir + "/" + tool;
136	    std::error_code ec;
137	    if (::access(cand.c_str(), X_OK) == 0 && !fs::is_directory(cand, ec))
138	      return cand;
139	  }
140	  return "";
141	}
142	
143	// Match `^\s*(?:export\s+)?HYBRID_TOOLCHAIN\s*=\s*(.+?)\s*$`; on match set `out`
144	// to the value with surrounding whitespace, then double, then single quotes
145	// stripped (mirrors hsim._read_hybrid_toolchain).
146	bool parse_toolchain_line(const std::string& line, std::string& out) {
147	  size_t i = 0, n = line.size();
148	  auto skip_ws = [&] {
149	    while (i < n && std::isspace(static_cast<unsigned char>(line[i]))) ++i;
150	  };
151	  skip_ws();
152	  const std::string kw = "export";
153	  if (line.compare(i, kw.size(), kw) == 0 && i + kw.size() < n &&
154	      std::isspace(static_cast<unsigned char>(line[i + kw.size()]))) {
155	    i += kw.size();
156	    skip_ws();
157	  }
158	  const std::string key = "HYBRID_TOOLCHAIN";
159	  if (line.compare(i, key.size(), key) != 0) return false;
160	  i += key.size();
161	  skip_ws();
162	  if (i >= n || line[i] != '=') return false;
163	  std::string rest = line.substr(i + 1);  // everything after '='
164	  if (rest.empty()) return false;         // regex (.+?) needs >= 1 char
165	  size_t b = 0, e = rest.size();
166	  while (b < e && std::isspace(static_cast<unsigned char>(rest[b]))) ++b;
167	  while (e > b && std::isspace(static_cast<unsigned char>(rest[e - 1]))) --e;
168	  std::string val = strip_char(rest.substr(b, e - b), '"');
169	  out = strip_char(val, '\'');
170	  return true;
171	}
172	
173	// HYBRID_TOOLCHAIN: env first (non-empty wins), else the first matching
174	// assignment in config.env. "" if neither yields a value.
175	std::string read_hybrid_toolchain() {
176	  const char* env = std::getenv("HYBRID_TOOLCHAIN");
177	  if (env && *env) return env;
178	  std::ifstream f(repo_root() / "config.env");
179	  if (!f) return "";
180	  std::string line, val;
181	  while (std::getline(f, line))
182	    if (parse_toolchain_line(line, val)) return val;
183	  return "";
184	}
185	
186	std::vector<Row> doctor_toolchain() {
187	  struct T {
188	    const char* tool;
189	    const char* hint;
190	    bool warn_only;  // a missing podman warns; make fails
191	  };
192	  const T tools[] = {
193	      {"make", "needed by scripts/build_all.sh of fixtures", false},
194	      {"podman", "needed by the external vsim repo's container build (or docker shim)", true},
195	  };
196	  std::vector<Row> rows;
197	  for (const T& t : tools) {
198	    std::string found = which(t.tool);
199	    if (!found.empty())
200	      rows.push_back({t.tool, "PASS", found});
201	    else
202	      rows.push_back({t.tool, t.warn_only ? "WARN" : "FAIL",
203	                      std::string("not on PATH -- ") + t.hint});
204	  }
205	
206	  std::string tc = read_hybrid_toolchain();
207	  if (tc.empty()) {
208	    rows.push_back({"HYBRID_TOOLCHAIN", "WARN",
209	                    "not set -- needed for fixture build (see config.env)"});
210	  } else {
211	    fs::path gcc = fs::path(tc) / "bin" / "riscv64-unknown-elf-gcc";
212	    if (fs::is_regular_file(gcc))
213	      rows.push_back({"riscv64-unknown-elf-gcc", "PASS", gcc.string()});
214	    else
215	      rows.push_back({"riscv64-unknown-elf-gcc", "FAIL",
216	                      "missing " + gcc.string() +
217	                          " -- check HYBRID_TOOLCHAIN=" + tc});
218	  }
219	  return rows;
220	}
