222	// --- runtime ----------------------------------------------------------------
223	
224	constexpr long kDefaultJobs = 8;
225	
226	std::vector<Row> doctor_runtime() {
227	  std::vector<Row> rows;
228	  long nproc = sysconf(_SC_NPROCESSORS_ONLN);
229	  if (nproc < 1) nproc = 1;
230	  rows.push_back({"nproc", "INFO", std::to_string(nproc)});
231	
232	  std::error_code ec;
233	  if (fs::is_directory("/dev/shm", ec)) {
234	    struct statvfs vfs{};
235	    unsigned long long free_gb = 0;
236	    if (statvfs("/dev/shm", &vfs) == 0)
237	      free_gb = static_cast<unsigned long long>(vfs.f_bavail) * vfs.f_frsize /
238	                (1024ULL * 1024 * 1024);
239	    rows.push_back({"/dev/shm free", free_gb >= 4 ? "PASS" : "WARN",
240	                    std::to_string(free_gb) + " GB"});
241	  } else {
242	    rows.push_back({"/dev/shm", "WARN",
243	                    "not present -- e2e fixtures will fall back to $TMPDIR"});
244	  }
245	
246	  long suggested = std::min(nproc, kDefaultJobs);
247	  rows.push_back({"JOBS suggestion", "INFO",
248	                  std::to_string(suggested) + " (default cap = " +
249	                      std::to_string(kDefaultJobs) + ")"});
250	  return rows;
251	}
252	
253	// --- engines (C++-only readout, after Summary) ------------------------------
254	
255	// Reflects `list engines` from the same F2 discovery, in doctor's row idiom.
256	// INFO-tagged and printed after Summary, so it never moves the summary counts
257	// or the exit code. Discovery warnings surface as WARN rows here.
258	void print_engines_section() {
259	  Discovery disc = discover_engines();
260	  size_t w = 0;
261	  for (const EngineDescriptor& e : disc.engines) w = std::max(w, e.id.size());
262	
263	  std::printf("\nengines:\n");
264	  for (const EngineDescriptor& e : disc.engines)
265	    std::printf("  [INFO] %s  kind=%s vlen=%s triggers=%s\n",
266	                ljust(e.id, w).c_str(), e.kind.c_str(), vlen_str(e.vlen).c_str(),
267	                join(e.triggers).c_str());
268	  for (const std::string& warn : disc.warnings)
269	    std::printf("  [WARN] %s\n", warn.c_str());
270	}
271	
272	// The shared-mmap backing tiers (F1 resolver order) with their free space,
273	// plus WSL2 advice. INFO/WARN-tagged and printed after Summary like engines,
274	// so the carried-over report keeps byte-parity with the Python golden.
275	void print_mmap_section() {
276	  const std::vector<MmapTier> tiers = mmap_tiers();
277	  size_t w = 0;
278	  for (const MmapTier& t : tiers) w = std::max(w, t.label.size());
279	
280	  std::printf("\nmmap tiers:\n");
281	  int n = 0;
282	  for (const MmapTier& t : tiers) {
283	    struct statvfs vfs{};
284	    std::string free = "missing";
285	    if (statvfs(t.dir.c_str(), &vfs) == 0) {
286	      const double gib = static_cast<double>(vfs.f_bavail) * vfs.f_frsize /
287	                         (1024.0 * 1024 * 1024);
288	      char buf[32];
289	      std::snprintf(buf, sizeof(buf), "free: %.1f GiB", gib);
290	      free = buf;
291	    }
292	    std::printf("  [INFO] tier %d  %s  %s\n", ++n, ljust(t.label, w).c_str(),
293	                free.c_str());
294	  }
295	
296	  std::string proc_version;
297	  if (std::FILE* f = std::fopen("/proc/version", "r")) {
298	    char buf[512] = {};
299	    const size_t got = std::fread(buf, 1, sizeof(buf) - 1, f);
300	    proc_version.assign(buf, got);
301	    std::fclose(f);
302	  }
303	  std::error_code ec;
304	  for (const std::string& warn :
305	       wsl_warnings(proc_version, fs::current_path(ec).string(), tiers))
306	    std::printf("  [WARN] %s\n", warn.c_str());
307	}
308	
309	struct Section {
310	  const char* title;
311	  std::vector<Row> rows;
312	};
313	
314	}  // namespace
315	
316	int cmd_doctor(const Cli&) {
317	  std::vector<Section> sections = {
318	      {"artifacts", doctor_artifacts()},
319	      {"submodules", doctor_submodules()},
320	      {"toolchain", doctor_toolchain()},
321	      {"runtime", doctor_runtime()},
322	  };
323	
324	  size_t name_width = 0;
325	  for (const Section& s : sections)
326	    for (const Row& r : s.rows) name_width = std::max(name_width, r.name.size());
327	
328	  int passes = 0, fails = 0, warns = 0;
329	  for (const Section& s : sections) {
330	    std::printf("%s:\n", s.title);
331	    for (const Row& r : s.rows) {
332	      if (r.status == "PASS") ++passes;
333	      else if (r.status == "FAIL") ++fails;
334	      else if (r.status == "WARN") ++warns;
335	      std::printf("  [%-4s] %s  %s\n", r.status.c_str(),
336	                  ljust(r.name, name_width).c_str(), r.detail.c_str());
337	    }
338	    std::printf("\n");
339	  }
340	  std::printf("Summary: %d PASS, %d FAIL, %d WARN\n", passes, fails, warns);
341	
342	  print_engines_section();
343	  print_mmap_section();
344	  return fails > 0 ? 1 : 0;
345	}
