21	// The bundled functional engine(s). QEMU does not implement --describe, so the
22	// descriptor is built in. builtin_qemu_arch(64) is the rv64 "qemu64";
23	// builtin_qemu_arch(32) is the rv32 "qemu32" (qemu-system-riscv32). The
24	// standalone (model=fast) run uses qemu's OWN default -cpu -- the user's post-`--`
25	// args (incl. an explicit -cpu) still win; only the rv64 hybrid fast-leg pins a
26	// -cpu. Binary path honors $VSIM_QEMU / $VSIM_QEMU32, then $QEMU_BIN_DIR (env or
27	// config.env), then the legacy in-tree build. Exposed (engine_registry.hpp) so
28	// `run --mode fast` resolves qemu directly, skipping the per-engine --describe
29	// scan whole-registry discovery would spawn.
30	EngineDescriptor builtin_qemu_arch(int xlen) {
31	  const bool rv32 = (xlen == 32);
32	  EngineDescriptor d;
33	  d.id = rv32 ? kQemuId32 : kQemuId64;
34	  d.type = "qemu";
35	  d.kind = "functional";
36	  d.xlen = xlen;
37	  d.triggers = {"marker", "pc"};
38	  d.state = {"drain"};
39	  d.source = "built-in";
40	
41	  d.roles = {"standalone"};
42	  if (!rv32) {  // hybrid rv32 (qemu32 fast-leg + engine-matched -cpu) not wired yet
43	    // The hybrid fast-forward leg (rv64): load the ELF, drain on the plugin's
44	    // trigger into {state_out}, exit 200. {plugin}/{mmap}/{mmap_size}/{state_out}
45	    // are filled by the plan executor (F6); {trigger} is the plugin comma-suffix
46	    // (empty for marker), folded by leg_trigger_args (F9).
47	    d.roles.push_back("fast-leg");
48	    // {qemu_cpu}: the accurate engine's CPU model (from its --print-qemu-config
49	    // driver globals; run_plan falls back to the andes-ax45mpv family default).
50	    // The -readconfig globals apply only to the driver they name, so the model
51	    // must follow the engine -- andes-ax45mpv silently kept vlen=512 when the
52	    // ax66 (VLEN 128) pairing asked for 128.
53	    d.invoke.push_back(
54	        {"fast-leg",
55	         {"{bin}", "-object",
56	          "memory-backend-file,id=mem,share=on,mem-path={mmap},size={mmap_size}",
57	          "-machine", "andes_ae350,memory-backend=mem", "-cpu",
58	          "{qemu_cpu},vlen={vlen}", "-nographic", "-semihosting-config",
59	          "enable=on,target=native", "-bios", "{elf}", "-plugin",
60	          "{plugin},outfile={state_out}{trigger}"}});
61	  }
62	
63	  // The standalone functional run (model=fast). andes_ae350's generic default
64	  // -cpu hangs the vplat fixtures, so pin a concrete andes core: the
65	  // vector-capable andes-ax46mpv (rv64) / andes-a46mpv (rv32). We pass NO vlen --
66	  // the cpu model's own QEMU default applies, so both scalar and vector binaries
67	  // run out of the box; a user who needs a specific width passes it via the
68	  // post-`--` -cpu (e.g. -cpu andes-ax46mpv,vlen=512), which still wins.
69	  // run_passthrough fills {bin}/{elf}.
70	  const char* fast_cpu = rv32 ? "andes-a46mpv" : "andes-ax46mpv";
71	  d.invoke.push_back(
72	      {"standalone",
73	       {"{bin}", "-machine", "andes_ae350", "-cpu", fast_cpu, "-nographic",
74	        "-semihosting-config", "enable=on,target=native", "-bios", "{elf}"}});
75	
76	  const std::string sys =
77	      std::string("qemu-system-") + (rv32 ? "riscv32" : "riscv64");
78	  const char* env = rv32 ? "VSIM_QEMU32" : "VSIM_QEMU";
79	  if (const char* q = std::getenv(env); q && *q)
80	    d.bin_path = q;
81	  else if (std::string qd = config_env_value("QEMU_BIN_DIR"); !qd.empty())
82	    d.bin_path = (fs::path(qd) / sys).string();
83	  else
84	    d.bin_path = (repo_root() / "build" / "qemu" / sys).string();
85	  return d;
86	}
