93	constexpr int kDescribeTimeoutMs = 5000;
94	
95	bool is_executable_file(const fs::path& p) {
96	  std::error_code ec;
97	  if (!fs::is_regular_file(p, ec)) return false;
98	  return ::access(p.c_str(), X_OK) == 0;
99	}
100	
101	std::string read_file(const fs::path& p) {
102	  std::ifstream f(p, std::ios::binary);
103	  std::ostringstream ss;
104	  ss << f.rdbuf();
105	  return ss.str();
106	}
