108	// Ask one binary to describe itself: try `<bin> --describe`, else read the
109	// <bin>.json sidecar. On success fills `d` and returns true; on failure leaves
110	// a human-readable note in `warn`.
111	bool describe_one(const fs::path& bin, EngineDescriptor& d, std::string& warn) {
112	  RunResult r = run_process({bin.string(), "--describe"}, kDescribeTimeoutMs);
113	  if (!r.spawn_failed && !r.timed_out && r.rc == 0) {
114	    json::Parsed p = json::parse(r.out);
115	    if (p.ok) {
116	      std::string err = descriptor_from_json(p.value, d);
117	      if (err.empty()) {
118	        d.bin_path = bin.string();
119	        d.source = "--describe";
120	        return true;
121	      }
122	      warn = bin.string() + ": --describe JSON invalid: " + err;
123	    } else {
124	      warn = bin.string() + ": --describe output is not JSON: " + p.error;
125	    }
126	  }
127	
128	  fs::path sidecar = bin;
129	  sidecar += ".json";
130	  std::error_code ec;
131	  if (fs::exists(sidecar, ec)) {
132	    json::Parsed p = json::parse(read_file(sidecar));
133	    if (p.ok) {
134	      EngineDescriptor sd;
135	      std::string err = descriptor_from_json(p.value, sd);
136	      if (err.empty()) {
137	        sd.bin_path = bin.string();
138	        sd.source = "sidecar";
139	        d = std::move(sd);
140	        return true;
141	      }
142	      warn = sidecar.string() + ": invalid descriptor: " + err;
143	    } else {
144	      warn = sidecar.string() + ": not JSON: " + p.error;
145	    }
146	  }
147	
148	  if (warn.empty()) warn = bin.string() + ": no --describe and no sidecar";
149	  return false;
150	}
151	
152	// `prefix` filters candidate basenames; empty accepts any executable. The
153	// default VSIM_BIN_DIR scan passes "sim_"; a user-curated engines dir passes
154	// "" so a drop-in alioth/sid (any name) is eligible. The naming convention thus
155	// lives in the call site, not in this engine-agnostic scanner.
156	void scan_dir(const fs::path& dir, std::string_view prefix, Discovery& out,
157	              std::set<std::string>& seen) {
158	  std::error_code ec;
159	  if (!fs::is_directory(dir, ec)) return;
160	
161	  std::vector<fs::path> entries;
162	  for (const auto& e : fs::directory_iterator(dir, ec)) entries.push_back(e.path());
163	  std::sort(entries.begin(), entries.end());  // stable, deterministic order
164	
165	  for (const fs::path& p : entries) {
166	    if (!prefix.empty() && !p.filename().string().starts_with(prefix)) continue;
167	    if (!is_executable_file(p)) continue;
168	    EngineDescriptor d;
169	    std::string warn;
170	    if (describe_one(p, d, warn)) {
171	      normalize_engine_label(d);  // verilator -> vsim, before dedup keys on id
172	      if (seen.insert(d.id).second) out.engines.push_back(std::move(d));
173	    } else if (!warn.empty()) {
174	      out.warnings.push_back(warn);
175	    }
176	  }
177	}
