182	// mirroring QEMU_BIN_DIR) resolved env-first then from config.env, so the driver
183	// finds the external vsim without a prior `source ./setup.sh`. Empty when
184	// unset everywhere -- there is no in-tree vsim to fall back to.
185	fs::path vsim_scan_dir(const fs::path& config_file) {
