193	Discovery discover_engines() {
194	  Discovery out;
195	  std::set<std::string> seen;
196	
197	  EngineDescriptor qemu = builtin_qemu();
198	  seen.insert(qemu.id);
199	  out.engines.push_back(std::move(qemu));
200	
201	  // rv32 functional engine, listed alongside qemu so `list engines` shows both
202	  // (its binary is qemu-system-riscv32 under the same QEMU_BIN_DIR).
203	  EngineDescriptor qemu32 = builtin_qemu_arch(32);
204	  seen.insert(qemu32.id);
205	  out.engines.push_back(std::move(qemu32));
206	
207	  if (const char* env = std::getenv("ANDESIM_ENGINES_DIR"); env && *env) {
208	    std::stringstream ss(env);
209	    std::string dir;
210	    while (std::getline(ss, dir, ':'))
211	      if (!dir.empty()) scan_dir(dir, /*prefix=*/"", out, seen);
212	  } else {
213	    scan_dir(vsim_scan_dir(), /*prefix=*/"sim_", out, seen);
214	  }
215	  return out;
216	}
