23	std::vector<uint8_t> build_manifest_blob(const std::string& app_path,
24	                                         uint64_t mem_size,
25	                                         const std::vector<std::string>& extra_argv,
26	                                         std::string& err) {
27	  err.clear();
28	  vlinux_manifest m{};
29	  m.magic = VLINUX_MANIFEST_MAGIC;
30	  m.version = VLINUX_MANIFEST_VERSION;
31	  m.mem_size = mem_size;
32	  if (app_path.size() >= sizeof(m.app_path)) {
33	    err = "app path too long for the manifest (" +
34	          std::to_string(app_path.size()) + " bytes, max " +
35	          std::to_string(sizeof(m.app_path) - 1) + "): " + app_path;
36	    return {};
37	  }
38	  std::memcpy(m.app_path, app_path.c_str(), app_path.size() + 1);  // + NUL
39	
40	  if (extra_argv.size() > VLINUX_MANIFEST_ARGV_MAX_COUNT) {
41	    err = "too many app args (" + std::to_string(extra_argv.size()) +
42	          ", max " + std::to_string(VLINUX_MANIFEST_ARGV_MAX_COUNT) + ")";
43	    return {};
44	  }
45	  size_t off = 0;
46	  for (const std::string& a : extra_argv) {
47	    const size_t need = a.size() + 1;  // + NUL
48	    if (off + need > sizeof(m.argv_extra_buf)) {
49	      err = "app args too long for the manifest (" +
50	            std::to_string(off + need) + " bytes, max " +
51	            std::to_string(sizeof(m.argv_extra_buf)) + ")";
52	      return {};
53	    }
54	    std::memcpy(m.argv_extra_buf + off, a.c_str(), need);
55	    off += need;
56	  }
57	  m.argv_extra_count = static_cast<uint32_t>(extra_argv.size());
58	  m.argv_extra_len = static_cast<uint32_t>(off);
59	
60	  std::vector<uint8_t> blob(sizeof(m));
61	  std::memcpy(blob.data(), &m, sizeof(m));
62	  return blob;
63	}
