65	std::vector<std::string> manifest_objcopy_argv(const std::string& objcopy_bin,
66	                                               const std::string& blob_path,
67	                                               const std::string& vlinux_elf) {
68	  return {objcopy_bin, "--update-section", ".manifest=" + blob_path,
69	          vlinux_elf};
