71	
72	std::string stage_linux_runtime(const std::string& app_elf_abs,
73	                                uint64_t mem_size,
74	                                const std::vector<std::string>& extra_argv,
75	                                std::string& err) {
76	  err.clear();
77	  const fs::path vlinux_src =
78	      repo_root() / "build" / "runtime" / "linux" / "vlinux.elf";
79	  std::error_code ec;
80	  if (!fs::is_regular_file(vlinux_src, ec)) {
81	    err = "vlinux.elf not built: " + vlinux_src.string() +
82	          " (run: bash scripts/build_all.sh vlinux)";
83	    return "";
84	  }
85	
86	  const std::string toolchain = config_env_value("HYBRID_TOOLCHAIN");
87	  if (toolchain.empty()) {
88	    err = "HYBRID_TOOLCHAIN not set (env or config.env; needed to run objcopy)";
89	    return "";
90	  }
91	  const std::string objcopy_bin = toolchain + "/bin/riscv64-unknown-elf-objcopy";
92	
93	  const std::string wd = make_temp_dir("andesim-linux");
94	  if (wd.empty()) {
95	    err = "failed to create a linux-runtime work dir";
96	    return "";
97	  }
98	
99	  const std::string vlinux_run = wd + "/vlinux-run.elf";
100	  fs::copy_file(vlinux_src, vlinux_run, fs::copy_options::overwrite_existing,
101	                ec);
102	  if (ec) {
103	    err = "failed to stage vlinux.elf: " + ec.message();
104	    return "";
105	  }
106	
107	  const std::vector<uint8_t> blob =
108	      build_manifest_blob(app_elf_abs, mem_size, extra_argv, err);
109	  if (!err.empty()) return "";
110	
111	  const std::string blob_path = wd + "/manifest.bin";
112	  std::ofstream bf(blob_path, std::ios::binary | std::ios::trunc);
113	  bf.write(reinterpret_cast<const char*>(blob.data()),
114	           static_cast<std::streamsize>(blob.size()));
115	  if (!bf) {
116	    err = "failed to write manifest blob: " + blob_path;
117	    return "";
118	  }
119	  bf.close();
120	
121	  const std::vector<std::string> argv =
122	      manifest_objcopy_argv(objcopy_bin, blob_path, vlinux_run);
123	  // The stamping step has no other visible trace (unlike the final engine
124	  // command, which --dry-run prints itself) -- always show it, so a dry run
125	  // actually previews the whole "what would land in vlinux-run.elf" story.
126	  log_line(kLogInfo, "[andesim] --runtime linux: exec %s",
127	           render_argv(argv).c_str());
128	  const RunResult r = run_process(argv, /*timeout_ms=*/10000);
129	  if (r.spawn_failed || r.timed_out || r.rc != 0) {
130	    err = "objcopy --update-section .manifest failed (rc=" +
131	          std::to_string(r.rc) + "): " + render_argv(argv);
132	    return "";
133	  }
134	  return vlinux_run;
135	}
