35	// memcpy a POD header out of the buffer at `off`; false if it would overrun
36	// (buffers may be truncated/malformed -- never read past the end).
37	template <class T>
38	bool load(const std::vector<char>& buf, size_t off, T& out) {
39	  if (off + sizeof(T) > buf.size()) return false;
40	  std::memcpy(&out, buf.data() + off, sizeof(T));
41	  return true;
42	}
