44	// Slurp `path` and validate its ELFCLASS64 header into `eh`. Returns false and
45	// sets `err` (unreadable / not-ELF / not-RV64) on failure, clears `err` on ok.
46	// Shared prologue for every ELF reader below.
47	bool read_elf64_header(const std::string& path, std::vector<char>& buf,
48	                       Elf64_Ehdr& eh, std::string& err) {
49	  err.clear();
50	  if (!slurp(path, buf)) {
51	    err = "cannot read ELF '" + path + "'";
52	    return false;
53	  }
54	  if (!load(buf, 0, eh) || std::memcmp(eh.e_ident, ELFMAG, SELFMAG) != 0) {
55	    err = "not an ELF file: " + path;
56	    return false;
57	  }
58	  if (eh.e_ident[EI_CLASS] != ELFCLASS64) {
59	    err = "not an RV64 (ELFCLASS64) file: " + path;
60	    return false;
61	  }
62	  return true;
63	}
