122	int elf_xlen(const std::string& elf_path) {
123	  // Only e_ident is needed (16 bytes, identical layout for both classes), so
124	  // read just that rather than slurping a whole (possibly large) ELF.
125	  std::ifstream f(elf_path, std::ios::binary);
126	  unsigned char ident[EI_NIDENT];
127	  if (!f.read(reinterpret_cast<char*>(ident), EI_NIDENT)) return 0;
128	  if (std::memcmp(ident, ELFMAG, SELFMAG) != 0) return 0;  // not an ELF
129	  switch (ident[EI_CLASS]) {
130	    case ELFCLASS32: return 32;
131	    case ELFCLASS64: return 64;
132	    default: return 0;
133	  }
134	}
