215	std::pair<uint64_t, uint64_t> fn_range(const std::string& elf_path, uint64_t addr) {
216	  std::vector<char> buf;
217	  Elf64_Ehdr eh;
218	  std::string ignored;
219	  if (!read_elf64_header(elf_path, buf, eh, ignored)) return {0, 0};
220	
221	  uint64_t best_value = 0;
222	  uint64_t best_size = 0;
223	  bool found = false;
224	
225	  for (unsigned i = 0; i < eh.e_shnum; ++i) {
226	    Elf64_Shdr sym_sh;
227	    if (!load(buf, eh.e_shoff + static_cast<size_t>(i) * eh.e_shentsize, sym_sh)) break;
228	    if (sym_sh.sh_type != SHT_SYMTAB || sym_sh.sh_entsize == 0) continue;
229	    const size_t nsym = sym_sh.sh_size / sym_sh.sh_entsize;
230	    for (size_t s = 0; s < nsym; ++s) {
231	      Elf64_Sym sym;
232	      if (!load(buf, sym_sh.sh_offset + s * sym_sh.sh_entsize, sym)) break;
233	      if (sym.st_shndx == SHN_UNDEF) continue;
234	      if (ELF64_ST_TYPE(sym.st_info) != STT_FUNC) continue;
235	      if (sym.st_value > addr) continue;
236	      if (sym.st_size != 0 && addr >= sym.st_value + sym.st_size) continue;
237	      if (found && sym.st_value <= best_value) continue;
238	      best_value = sym.st_value;
239	      best_size = sym.st_size;
240	      found = true;
241	    }
242	  }
243	
244	  if (!found || best_size == 0) return {0, 0};
245	  return {best_value, best_value + best_size};
246	}
