248	RoiMarkerPcs find_roi_markers(const std::string& elf_path) {
249	  RoiMarkerPcs out;
250	  std::vector<char> buf;
251	  Elf64_Ehdr eh;
252	  std::string ignored;  // never errors -- both fields staying 0 is the signal
253	  if (!read_elf64_header(elf_path, buf, eh, ignored)) return out;
254	
255	  for (uint16_t i = 0; i < eh.e_phnum; ++i) {
256	    Elf64_Phdr ph;
257	    const size_t phoff = static_cast<size_t>(eh.e_phoff) +
258	                         static_cast<size_t>(i) * eh.e_phentsize;
259	    if (!load(buf, phoff, ph)) break;
260	    if (ph.p_type != PT_LOAD || (ph.p_flags & PF_X) == 0) continue;
261	    if (ph.p_offset + ph.p_filesz > buf.size()) continue;  // truncated file
262	
263	    // Mirror hybrid::CsrTrigger::scan_buffer's own walk exactly: a 2-byte
264	    // stride, since RVC (compressed) instructions can leave a 4-byte
265	    // marker starting at a non-4-aligned offset. SLTI has no compressed
266	    // form, so a genuine marker is always the 4-byte case below.
267	    size_t off = 0;
268	    while (off + sizeof(uint16_t) <= ph.p_filesz) {
269	      uint16_t lo;
270	      std::memcpy(&lo, buf.data() + ph.p_offset + off, sizeof(lo));
271	      const bool is_32 = (lo & 0x3u) == 0x3u;
272	      if (is_32) {
273	        if (off + sizeof(uint32_t) > ph.p_filesz) break;
274	        uint32_t insn;
275	        std::memcpy(&insn, buf.data() + ph.p_offset + off, sizeof(insn));
276	        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
277	        if (hybrid_match_handoff_insn(insn, &kind)) {
278	          const uint64_t pc = ph.p_vaddr + off;
279	          if (kind == HYBRID_HANDOFF_ENTER) out.enter_pc = pc;
280	          else if (kind == HYBRID_HANDOFF_EXIT) out.exit_pc = pc;
281	        }
282	        off += sizeof(uint32_t);
283	      } else {
284	        off += sizeof(uint16_t);
285	      }
286	    }
287	  }
288	  return out;
289	}
