19	
20	DiffReport diff_states(const hybrid_state_v1& ref, const hybrid_state_v1& got,
21	                       const std::vector<std::string>& andes_supported) {
22	  DiffReport r;
23	
24	  cmp(r, "magic", ref.magic, got.magic);
25	  cmp(r, "version", ref.version, got.version);
26	  cmp(r, "flags", ref.flags, got.flags);
27	  cmp(r, "hart_id", ref.hart_id, got.hart_id);
28	  cmp(r, "priv", ref.priv, got.priv);
29	  cmp(r, "pc", ref.pc, got.pc);
30	
31	  // mepc/mcause: in the trap-free hybrid ROI they round-trip (L24: restored at
32	  // resume, re-read at drain). mtval/mstatus stay out of scope where they are
33	  // implementation-defined / carry dirty bits (false positives).
34	  cmp(r, "mepc", ref.mepc, got.mepc);
35	  cmp(r, "mcause", ref.mcause, got.mcause);
36	
37	  // Round-trip M-mode CSRs: mscratch (L23) and mtval/mie (L24) are restored at
38	  // resume and re-read at drain, so a trap-free ROI must match the oracle on
39	  // them. mip is excluded: its pending bits are hardware/platform-driven
40	  // (timer/external) and diverge between QEMU's functional clock and vsim's
41	  // cycle clock even with no trap (it still round-trips into the drained
42	  // record, just not the verifier).
43	  cmp(r, "mscratch", ref.mscratch, got.mscratch);
44	  cmp(r, "mtval", ref.mtval, got.mtval);
45	  cmp(r, "mie", ref.mie, got.mie);
46	
47	  // Membership in the engine's --describe `andes_csrs` list (also used by
48	  // the X-macro block gating below, where an empty list means compare-all).
49	  auto in_list = [&](std::string_view name) {
50	    for (const std::string& s : andes_supported)
51	      if (s == name) return true;
52	    return false;
53	  };
54	
55	  // S/U trap CSRs (ax66 registration, option A): on an S-mode engine whose
56	  // --describe names them they round-trip (restored at resume, re-read at
57	  // drain), so the verifier compares them. Gated on the EXPLICIT name: an
58	  // empty list (no engine info) or an M-only engine keeps the passthrough
59	  // skip -- unlike the X-macro blocks, empty does NOT mean compare-all here,
60	  // because M-only engines never restore these.
61	  if (in_list("satp"))    cmp(r, "satp",    ref.satp,    got.satp);
62	  if (in_list("medeleg")) cmp(r, "medeleg", ref.medeleg, got.medeleg);
63	  if (in_list("mideleg")) cmp(r, "mideleg", ref.mideleg, got.mideleg);
64	
65	  for (int i = 0; i < 32; ++i)
66	    cmp(r, "x" + std::to_string(i), ref.gpr[i], got.gpr[i]);
67	
68	  if (ref.flags & HYBRID_FLAG_FP) {
69	    for (int i = 0; i < 32; ++i)
70	      cmp(r, "f" + std::to_string(i), ref.fpr[i], got.fpr[i]);
71	    cmp(r, "fcsr", ref.fcsr, got.fcsr);  // L20: frm + sticky fflags
72	  }
73	
74	  if (ref.flags & HYBRID_FLAG_V) {
75	    cmp(r, "vstart", ref.vstart, got.vstart);
76	    cmp(r, "vtype", ref.vtype, got.vtype);
77	    cmp(r, "vl", ref.vl, got.vl);
78	    cmp(r, "vlenb", ref.vlenb, got.vlenb);
79	    cmp(r, "vxsat", ref.vxsat, got.vxsat);
80	    cmp(r, "vxrm", ref.vxrm, got.vxrm);
81	    cmp(r, "vcsr", ref.vcsr, got.vcsr);
82	
83	    // One compared "field" per vector register; report the first differing
84	    // byte as "v<i>[<byte>]".
85	    for (int i = 0; i < 32; ++i) {
86	      ++r.compared;
87	      const uint8_t* a = &ref.vreg[static_cast<size_t>(i) * HYBRID_VLEN_BYTES_MAX];
88	      const uint8_t* b = &got.vreg[static_cast<size_t>(i) * HYBRID_VLEN_BYTES_MAX];
89	      for (int j = 0; j < HYBRID_VLEN_BYTES_MAX; ++j) {
90	        if (a[j] != b[j]) {
91	          r.diffs.push_back({"v" + std::to_string(i) + "[" +
92	                                 std::to_string(j) + "]",
93	                             a[j], b[j]});
94	          break;
95	        }
96	      }
97	    }
98	  }
99	
100	  // Andes V5 CSR block (v3): the boot-static memory-system/extension CSRs plus
101	  // the DSP overflow flag round-trip through the trap-free ROI (ResumeDriver
102	  // restores them, StateDrain re-reads them), so a correct transport matches the
103	  // oracle. The X-macro is the single source of truth shared with the plugin
104	  // drain / resume / drain re-read, so this list can never drift out of sync.
105	  //
106	  // Exclusion: msp_bound/msp_base are the HW stack-protection bound registers.
107	  // QEMU resets them to all-ones; a vsim core that does not implement HW stack
108	  // protection drains 0. That divergence is an engine-implementation artifact,
109	  // not a transport bug (the restore is a tolerant no-op on a core lacking the
110	  // CSR) -- so they are transported but excluded from strict verify, exactly
111	  // like mip's hardware-driven pending bits.
112	  auto andes_verify_excluded = [](std::string_view name) {
113	    // msp_bound/msp_base: engine-reset-divergent HW stack-protection bounds.
114	    // milmb/mdlmb: ILM/DLM base+enable CSRs. The base address round-trips, but
115	    // the enable bit (bit 0) is HW-presence state -- the vsim RTL has the local
116	    // memories and drains EN=1, while QEMU models none and drains EN=0. Same
117	    // class as msp_bound/msp_base (an engine-implementation artifact, not a
118	    // transport bug), so excluded rather than half-compared via a bit mask.
119	    // mhpmcounter3..6: hardware performance counters that increment DURING the
120	    // ROI, so the vsim (cycle) and QEMU (functional) values legitimately differ
121	    // -- transported and restored, but not strict-compared, like mcycle/mip.
122	    // mdcause: vsim models it as HW-set (a direct write drains back 0).
123	    // tdata1/tcontrol/mcontext: debug-trigger state whose reset defaults and
124	    // WARL widths differ between QEMU and vsim. All transported + restored, but
125	    // not cross-engine strict-compared.
126	    // mnvec: QEMU resets it to 0; the Andes RTL resets it to the hart's reset
127	    // vector and WARL-holds it (a restore write of 0 does not take), so a
128	    // trap-free ROI always false-diffs. Seen live on both engines when the
129	    // registration audit first claimed it (spec: "IM Requirement: Required").
130	    static constexpr std::string_view kExcluded[] = {
131	        "msp_bound", "msp_base", "milmb", "mdlmb",
132	        "mhpmcounter3", "mhpmcounter4", "mhpmcounter5", "mhpmcounter6",
133	        "mdcause", "tdata1", "tcontrol", "mcontext", "mnvec"};
134	    for (std::string_view e : kExcluded)
135	      if (e == name) return true;
136	    return false;
137	  };
138	  // Engine capability gate (S4): skip any Andes CSR the cycle engine does not
139	  // implement. Empty list = no engine info -> compare all (back-compat).
140	  auto andes_supported_csr = [&](std::string_view name) {
141	    return andes_supported.empty() || in_list(name);
142	  };
143	  // v6 write-mask gate: skip any mask-governed CSR the program never WROTE
144	  // (per the oracle's mask, which covers boot + ROI). Unwritten CSRs hold
145	  // QEMU's reset default in `ref` but the engine's own RTL reset in `got`
146	  // (the restore skipped them too), so comparing would false-positive on
147	  // every reset-value divergence. Flag clear = pre-v6 file = compare all.
148	  auto wm_live = [&](int slot) {
149	    if (!(ref.flags & HYBRID_FLAG_WRITE_MASK)) return true;
150	    return hybrid_wm_test(ref.write_mask, static_cast<unsigned>(slot)) != 0;
151	  };
152	  if (ref.flags & HYBRID_FLAG_ANDES) {
153	#define X(field, addr, name)                                     \
154	  if (!andes_verify_excluded(name) && andes_supported_csr(name)  \
155	      && wm_live(HYBRID_WM_ANDES_BASE + HYBRID_WM_ANDES_IDX_##field)) \
156	    cmp(r, name, ref.andes.field, got.andes.field);
157	    HYBRID_ANDES_CSR_LIST(X)
158	#undef X
159	    if (andes_supported_csr("pmacfg"))
160	      for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
161	        if (wm_live(HYBRID_WM_PMACFG_BASE + i))
162	          cmp(r, "pmacfg" + std::to_string(i), ref.andes.pmacfg[i],
163	              got.andes.pmacfg[i]);
164	    if (andes_supported_csr("pmaaddr"))
165	      for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
166	        if (wm_live(HYBRID_WM_PMAADDR_BASE + i))
167	          cmp(r, "pmaaddr" + std::to_string(i), ref.andes.pmaaddr[i],
168	              got.andes.pmaaddr[i]);
169	  }
170	
171	  // M-ext CSR block (v4): same gate (the engine's supported list now includes
172	  // the M-ext names) and the same HW-driven exclusion. A CSR the engine lacks
173	  // is neither restored, drained, nor compared.
174	  if (ref.flags & HYBRID_FLAG_M_EXT) {
175	#define X(field, addr, name)                                     \
176	  if (!andes_verify_excluded(name) && andes_supported_csr(name)  \
177	      && wm_live(HYBRID_WM_M_EXT_BASE + HYBRID_WM_M_EXT_IDX_##field)) \
178	    cmp(r, name, ref.m_ext.field, got.m_ext.field);
179	    HYBRID_M_EXT_CSR_LIST(X)
180	#undef X
181	  }
182	
183	  // L2C/L3C MMIO config (v5): the platform cache's Control Register
184	  // round-trips (restored at resume, re-read at drain) -- but only its
185	  // POLICY bits [7:0] (CEN, PFTHRES, IPFDPT, DPFDPT, ECCEN). The resume
186	  // side MERGES those over the target's live Control, leaving the RTL's
187	  // RAM-timing fields [13:8] and read-only status (INITSTATUS[14], COHSTA)
188	  // untouched, so the vsim drain and the QEMU oracle (a zero-filled RAM
189	  // stub) differ above bit 7 BY CONSTRUCTION: compare under the policy
190	  // mask. The read-only Configuration Register and the volatile
191	  // CCTL/error/counter registers are captured but not restored, so they
192	  // are not compared at all.
193	  if (ref.flags & HYBRID_FLAG_L2C) {
194	    cmp(r, "l2c.ctrl",
195	        ref.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8] & HYBRID_L2C_CTRL_POLICY_MASK,
196	        got.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8] & HYBRID_L2C_CTRL_POLICY_MASK);
197	  }
198	
199	  return r;
200	}
