202	std::vector<std::string> unsupported_written_csrs(
203	    const hybrid_state_v1& st, const std::vector<std::string>& andes_supported) {
204	  std::vector<std::string> out;
205	  if (!(st.flags & HYBRID_FLAG_WRITE_MASK)) return out;  // pre-v6: no info
206	  if (andes_supported.empty()) return out;               // no engine info
207	
208	  const auto supported = [&](std::string_view name) {
209	    for (const std::string& s : andes_supported)
210	      if (s == name) return true;
211	    return false;
212	  };
213	  const auto written = [&](int slot) {
214	    return hybrid_wm_test(st.write_mask, static_cast<unsigned>(slot)) != 0;
215	  };
216	
217	  // Andes scalars. ucode is skipped: the plugin sets its bit unconditionally
218	  // (transport-always DSP flag), so it carries no real write information.
219	#define X(field, addr, name)                                              \
220	  if (std::string_view{name} != "ucode"                                   \
221	      && written(HYBRID_WM_ANDES_BASE + HYBRID_WM_ANDES_IDX_##field)      \
222	      && !supported(name))                                                \
223	    out.push_back(name);
224	  HYBRID_ANDES_CSR_LIST(X)
225	#undef X
226	
227	  // PMA: one group marker each, matching the --describe list's convention.
228	  for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
229	    if (written(HYBRID_WM_PMACFG_BASE + i) && !supported("pmacfg")) {
230	      out.push_back("pmacfg");
231	      break;
232	    }
233	  for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
234	    if (written(HYBRID_WM_PMAADDR_BASE + i) && !supported("pmaaddr")) {
235	      out.push_back("pmaaddr");
236	      break;
237	    }
238	
239	#define X(field, addr, name)                                              \
240	  if (written(HYBRID_WM_M_EXT_BASE + HYBRID_WM_M_EXT_IDX_##field)         \
241	      && !supported(name))                                                \
242	    out.push_back(name);
243	  HYBRID_M_EXT_CSR_LIST(X)
244	#undef X
245	
246	  return out;
247	}
248	
249	std::string unsupported_written_warning(
250	    const hybrid_state_v1& st, const std::vector<std::string>& andes_supported,
251	    const std::string& engine_id) {
252	  const auto bad = unsupported_written_csrs(st, andes_supported);
253	  if (bad.empty()) return {};
254	  std::string names;
255	  for (const std::string& n : bad) {
256	    if (!names.empty()) names += ", ";
257	    names += n;
258	  }
259	  return "[andesim] warning: the program wrote CSRs engine " + engine_id +
260	         " does not implement: " + names +
261	         " (on this engine's silicon these writes would trap; the hybrid "
262	         "restore skipped them)\n";
263	}
264	
265	void print_diff_report(const DiffReport& r) {
266	  for (const FieldDiff& d : r.diffs)
267	    std::printf("[state-diff] %s: ref=0x%llx got=0x%llx\n", d.field.c_str(),
268	                d.ref, d.got);
269	  if (r.ok()) {
270	    std::printf(
271	        "[state-diff] PASS: %d fields match (counters and passthrough CSRs "
272	        "excluded)\n",
273	        r.compared);
274	  } else {
275	    std::printf("[state-diff] FAIL: %zu mismatch(es) (%d fields compared)\n",
276	                r.diffs.size(), r.compared);
277	  }
278	}
