1	// A small, dependency-free JSON reader for andesim.
2	//
3	// The framework may depend only on libc++ + the shared ABI header, so it
4	// cannot pull in a third-party JSON library. This parser covers exactly what
5	// engine descriptors (and later cluster/meta files) need: objects, arrays,
6	// strings (with the standard escapes), numbers, and the true/false/null
7	// literals. It is strict -- trailing junk is an error -- and never throws or
8	// crashes on malformed input; it reports `ok=false` instead.
9	#ifndef ANDESIM_JSON_HPP
10	#define ANDESIM_JSON_HPP
11	
12	#include <cstdint>
13	#include <string>
14	#include <string_view>
15	#include <vector>
16	
17	namespace andes_sim::json {
18	
19	// Object members are held as parallel keys[]/vals[] rather than a
20	// vector<pair<string,Value>>: std::vector supports an incomplete value type
21	// (needed for this recursive struct), but std::pair does not.
22	struct Value {
23	  enum class Type { Null, Bool, Number, String, Array, Object };
24	  Type type = Type::Null;
25	  bool b = false;
26	  double num = 0;
27	  std::string str;
28	  std::vector<Value> arr;          // array elements
29	  std::vector<std::string> keys;   // object member names (parallel to vals)
30	  std::vector<Value> vals;         // object member values
31	
32	  bool is_object() const { return type == Type::Object; }
33	  bool is_array() const { return type == Type::Array; }
34	  bool is_string() const { return type == Type::String; }
35	  bool is_number() const { return type == Type::Number; }
36	
37	  // Object member lookup; nullptr if not an object or key absent.
38	  const Value* find(std::string_view key) const {
39	    if (type != Type::Object) return nullptr;
40	    for (size_t k = 0; k < keys.size(); ++k)
41	      if (keys[k] == key) return &vals[k];
42	    return nullptr;
43	  }
44	
45	  std::string as_string(const std::string& dflt = "") const {
46	    return type == Type::String ? str : dflt;
47	  }
48	  long as_int(long dflt = 0) const {
49	    return type == Type::Number ? static_cast<long>(num) : dflt;
50	  }
51	  // For arrays of strings; non-string elements are skipped.
52	  std::vector<std::string> as_string_array() const {
53	    std::vector<std::string> out;
54	    if (type == Type::Array)
55	      for (const Value& e : arr)
56	        if (e.type == Type::String) out.push_back(e.str);
57	    return out;
58	  }
59	};
60	
61	struct Parsed {
62	  bool ok = false;
63	  Value value;
64	  std::string error;
65	};
66	
67	namespace detail {
68	
69	struct Parser {
70	  std::string_view s;
71	  size_t i = 0;
72	  std::string err;
73	
74	  bool fail(const char* m) {
75	    if (err.empty()) err = m;
76	    return false;
77	  }
78	  void skip_ws() {
79	    while (i < s.size() &&
80	           (s[i] == ' ' || s[i] == '\t' || s[i] == '\n' || s[i] == '\r'))
81	      ++i;
82	  }
83	
84	  static void encode_utf8(uint32_t cp, std::string& out) {
85	    if (cp < 0x80) {
86	      out.push_back(static_cast<char>(cp));
87	    } else if (cp < 0x800) {
88	      out.push_back(static_cast<char>(0xC0 | (cp >> 6)));
89	      out.push_back(static_cast<char>(0x80 | (cp & 0x3F)));
90	    } else {
91	      out.push_back(static_cast<char>(0xE0 | (cp >> 12)));
92	      out.push_back(static_cast<char>(0x80 | ((cp >> 6) & 0x3F)));
93	      out.push_back(static_cast<char>(0x80 | (cp & 0x3F)));
94	    }
95	  }
96	
97	  bool parse_string(std::string& out) {
98	    if (i >= s.size() || s[i] != '"') return fail("expected string");
99	    ++i;
100	    while (i < s.size()) {
101	      char c = s[i++];
102	      if (c == '"') return true;
103	      if (c == '\\') {
104	        if (i >= s.size()) return fail("dangling escape");
105	        char e = s[i++];
106	        switch (e) {
107	          case '"': out.push_back('"'); break;
108	          case '\\': out.push_back('\\'); break;
109	          case '/': out.push_back('/'); break;
110	          case 'b': out.push_back('\b'); break;
111	          case 'f': out.push_back('\f'); break;
112	          case 'n': out.push_back('\n'); break;
113	          case 'r': out.push_back('\r'); break;
114	          case 't': out.push_back('\t'); break;
115	          case 'u': {
116	            if (i + 4 > s.size()) return fail("bad \\u escape");
117	            uint32_t cp = 0;
118	            for (int k = 0; k < 4; ++k) {
119	              char h = s[i++];
120	              cp <<= 4;
121	              if (h >= '0' && h <= '9') cp |= static_cast<uint32_t>(h - '0');
122	              else if (h >= 'a' && h <= 'f') cp |= static_cast<uint32_t>(h - 'a' + 10);
123	              else if (h >= 'A' && h <= 'F') cp |= static_cast<uint32_t>(h - 'A' + 10);
124	              else return fail("bad hex in \\u escape");
125	            }
126	            encode_utf8(cp, out);
127	            break;
128	          }
129	          default: return fail("bad escape char");
130	        }
131	      } else {
132	        out.push_back(c);
133	      }
134	    }
135	    return fail("unterminated string");
136	  }
137	
138	  bool parse_number(Value& out) {
139	    size_t start = i;
140	    if (i < s.size() && s[i] == '-') ++i;
141	    while (i < s.size() && s[i] >= '0' && s[i] <= '9') ++i;
142	    if (i < s.size() && s[i] == '.') {
143	      ++i;
144	      while (i < s.size() && s[i] >= '0' && s[i] <= '9') ++i;
145	    }
146	    if (i < s.size() && (s[i] == 'e' || s[i] == 'E')) {
147	      ++i;
148	      if (i < s.size() && (s[i] == '+' || s[i] == '-')) ++i;
149	      while (i < s.size() && s[i] >= '0' && s[i] <= '9') ++i;
150	    }
151	    if (i == start) return fail("invalid number");
152	    std::string tok(s.substr(start, i - start));
153	    try {
154	      out.type = Value::Type::Number;
155	      out.num = std::stod(tok);
156	    } catch (...) {
157	      return fail("unparseable number");
158	    }
159	    return true;
160	  }
161	
162	  bool parse_lit(std::string_view lit, Value v, Value& out) {
163	    if (s.substr(i, lit.size()) != lit) return fail("invalid literal");
164	    i += lit.size();
165	    out = std::move(v);
166	    return true;
167	  }
168	
169	  bool parse_array(Value& out) {
170	    ++i;  // consume '['
171	    out.type = Value::Type::Array;
172	    skip_ws();
173	    if (i < s.size() && s[i] == ']') { ++i; return true; }
174	    while (true) {
175	      Value e;
176	      if (!parse_value(e)) return false;
177	      out.arr.push_back(std::move(e));
178	      skip_ws();
179	      if (i >= s.size()) return fail("unterminated array");
180	      if (s[i] == ',') { ++i; skip_ws(); continue; }
181	      if (s[i] == ']') { ++i; return true; }
182	      return fail("expected ',' or ']'");
183	    }
184	  }
185	
186	  bool parse_object(Value& out) {
187	    ++i;  // consume '{'
188	    out.type = Value::Type::Object;
189	    skip_ws();
190	    if (i < s.size() && s[i] == '}') { ++i; return true; }
191	    while (true) {
192	      skip_ws();
193	      std::string key;
194	      if (!parse_string(key)) return false;
195	      skip_ws();
196	      if (i >= s.size() || s[i] != ':') return fail("expected ':'");
197	      ++i;
198	      Value val;
199	      if (!parse_value(val)) return false;
200	      out.keys.push_back(std::move(key));
201	      out.vals.push_back(std::move(val));
202	      skip_ws();
203	      if (i >= s.size()) return fail("unterminated object");
204	      if (s[i] == ',') { ++i; continue; }
205	      if (s[i] == '}') { ++i; return true; }
206	      return fail("expected ',' or '}'");
207	    }
208	  }
209	
210	  bool parse_value(Value& out) {
211	    skip_ws();
212	    if (i >= s.size()) return fail("unexpected end of input");
213	    char c = s[i];
214	    if (c == '"') {
215	      out.type = Value::Type::String;
216	      return parse_string(out.str);
217	    }
218	    if (c == '{') return parse_object(out);
219	    if (c == '[') return parse_array(out);
220	    if (c == 't') { Value v; v.type = Value::Type::Bool; v.b = true; return parse_lit("true", std::move(v), out); }
221	    if (c == 'f') { Value v; v.type = Value::Type::Bool; v.b = false; return parse_lit("false", std::move(v), out); }
222	    if (c == 'n') { Value v; v.type = Value::Type::Null; return parse_lit("null", std::move(v), out); }
223	    if (c == '-' || (c >= '0' && c <= '9')) return parse_number(out);
224	    return fail("unexpected character");
225	  }
226	};
227	
228	}  // namespace detail
229	
230	inline Parsed parse(std::string_view text) {
231	  detail::Parser p{};
232	  p.s = text;
233	  Parsed result;
234	  p.skip_ws();
235	  if (!p.parse_value(result.value)) {
236	    result.ok = false;
237	    result.error = p.err.empty() ? "parse error" : p.err;
238	    return result;
239	  }
240	  p.skip_ws();
241	  if (p.i != p.s.size()) {
242	    result.ok = false;
243	    result.error = "trailing characters after JSON value";
244	    return result;
245	  }
246	  result.ok = true;
247	  return result;
248	}
249	
250	}  // namespace andes_sim::json
251	
252	#endif  // ANDESIM_JSON_HPP
