1	// Small text/CLI-value helpers shared across the command implementations.
2	// Header-only; no dependencies beyond the standard library.
3	#ifndef ANDESIM_STRUTIL_HPP
4	#define ANDESIM_STRUTIL_HPP
5	
6	#include <string>
7	#include <vector>
8	
9	namespace andes_sim {
10	
11	// A "" -> `def` positive-int CLI knob (e.g. --limit, --min-iters,
12	// --step-timeout-ms): empty string keeps the default; otherwise the whole
13	// string must parse as a positive integer or this returns false.
14	inline bool parse_positive_int(const std::string& v, int def, int& out) {
15	  if (v.empty()) {
16	    out = def;
17	    return true;
18	  }
19	  try {
20	    size_t pos = 0;
21	    out = std::stoi(v, &pos);
22	    return pos == v.size() && out > 0;
23	  } catch (...) {
24	    return false;
25	  }
26	}
27	
28	// Left-justify `s` to width `w` (pad with spaces; never truncate).
29	inline std::string ljust(std::string s, size_t w) {
30	  if (s.size() < w) s.append(w - s.size(), ' ');
31	  return s;
32	}
33	
34	// Join `v` with `sep` between elements.
35	inline std::string join(const std::vector<std::string>& v, const char* sep = ",") {
36	  std::string s;
37	  for (size_t k = 0; k < v.size(); ++k) {
38	    if (k) s += sep;
39	    s += v[k];
40	  }
41	  return s;
42	}
43	
44	// Engine HW width param (VLEN/DLEN/ELEN/XLEN) for display: a positive width
45	// prints as its number, 0/absent "-".
46	inline std::string vlen_str(long v) {
47	  return v > 0 ? std::to_string(v) : std::string("-");
48	}
49	
50	}  // namespace andes_sim
51	
52	#endif  // ANDESIM_STRUTIL_HPP
