19	std::string vformat(const char* fmt, va_list ap) {
20	  va_list ap2;
21	  va_copy(ap2, ap);
22	  const int n = std::vsnprintf(nullptr, 0, fmt, ap2);
23	  va_end(ap2);
24	  if (n <= 0) return "";
25	  std::string s(static_cast<size_t>(n), '\0');
26	  std::vsnprintf(s.data(), s.size() + 1, fmt, ap);
27	  return s;
28	}
