30	// Console when the threshold passes; the sink (timestamped, level-tagged)
31	// unconditionally.
32	void emit(int level, std::FILE* console, const std::string& text) {
33	  if (log_on(level)) {
34	    std::fputs(text.c_str(), console);
35	    std::fputc('\n', console);
36	  }
37	  if (g_sink) {
38	    char ts[24];
39	    const std::time_t now = std::time(nullptr);
40	    std::tm tm{};
41	    gmtime_r(&now, &tm);
42	    std::strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm);
43	    std::fprintf(g_sink, "[%s] [%s] %s\n", ts, level_name(level), text.c_str());
44	    std::fflush(g_sink);
45	  }
46	}
