49	bool set_log_threshold(const std::string& cli_value) {
50	  if (cli_value.empty()) return true;
51	  if (cli_value.size() != 1 || cli_value[0] < '0' || cli_value[0] > '6')
52	    return false;
53	  g_threshold = cli_value[0] - '0';
54	  return true;
55	}
